import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

__global__ void conv3d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int stride, int pad, int dilation, int groups,
    bool has_bias)
{
    long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long total = (long long)N * C_out * D_out * H_out * W_out;
    if (idx >= total) return;

    int w_out = (int)(idx % W_out);
    int h_out = (int)((idx / W_out) % H_out);
    int d_out = (int)((idx / ((long long)W_out * H_out)) % D_out);
    int c_out = (int)((idx / ((long long)W_out * H_out * D_out)) % C_out);
    int n     = (int)(idx / ((long long)W_out * H_out * D_out * C_out));

    int c_in_per_group  = C_in / groups;
    int c_out_per_group = C_out / groups;
    int g = c_out / c_out_per_group;

    float sum = has_bias ? bias[c_out] : 0.0f;

    for (int c = 0; c < c_in_per_group; ++c) {
        int c_in = g * c_in_per_group + c;
        #pragma unroll
        for (int kd = 0; kd < kD; ++kd) {
            int d_in = d_out * stride - pad + kd * dilation;
            if (d_in < 0 || d_in >= D_in) continue;
            #pragma unroll
            for (int kh = 0; kh < kH; ++kh) {
                int h_in = h_out * stride - pad + kh * dilation;
                if (h_in < 0 || h_in >= H_in) continue;
                #pragma unroll
                for (int kw = 0; kw < kW; ++kw) {
                    int w_in = w_out * stride - pad + kw * dilation;
                    if (w_in < 0 || w_in >= W_in) continue;
                    long long in_idx = ((((long long)n * C_in + c_in) * D_in + d_in) * H_in + h_in) * W_in + w_in;
                    long long w_idx  = ((((long long)c_out * c_in_per_group + c) * kD + kd) * kH + kh) * kW + kw;
                    sum += input[in_idx] * weight[w_idx];
                }
            }
        }
    }
    output[idx] = sum;
}

torch::Tensor conv3d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                             int64_t stride, int64_t padding, int64_t dilation, int64_t groups)
{
    auto x = input.contiguous();
    auto w = weight.contiguous();

    TORCH_CHECK(x.dim() == 5, "input must be 5D (N, C, D, H, W)");
    TORCH_CHECK(w.dim() == 5, "weight must be 5D (C_out, C_in/groups, kD, kH, kW)");
    TORCH_CHECK(x.is_cuda() && w.is_cuda(), "input and weight must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
                "input and weight must be float32");

    int N     = (int)x.size(0);
    int C_in  = (int)x.size(1);
    int D_in  = (int)x.size(2);
    int H_in  = (int)x.size(3);
    int W_in  = (int)x.size(4);

    int C_out = (int)w.size(0);
    int kD    = (int)w.size(2);
    int kH    = (int)w.size(3);
    int kW    = (int)w.size(4);

    int D_out = (int)((D_in + 2 * padding - dilation * (kD - 1) - 1) / stride + 1);
    int H_out = (int)((H_in + 2 * padding - dilation * (kH - 1) - 1) / stride + 1);
    int W_out = (int)((W_in + 2 * padding - dilation * (kW - 1) - 1) / stride + 1);

    auto out = torch::empty({N, C_out, D_out, H_out, W_out}, x.options());

    long long total = (long long)N * C_out * D_out * H_out * W_out;
    if (total == 0) return out;

    bool has_bias = bias.defined() && bias.numel() > 0;
    const float* bias_ptr = has_bias ? bias.contiguous().data_ptr<float>() : nullptr;

    int threads = 256;
    long long blocks = (total + threads - 1) / threads;

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    conv3d_forward_kernel<<<(unsigned int)blocks, threads, 0, stream>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        bias_ptr,
        out.data_ptr<float>(),
        N, C_in, D_in, H_in, W_in,
        C_out, D_out, H_out, W_out,
        kD, kH, kW,
        (int)stride, (int)padding, (int)dilation, (int)groups,
        has_bias);

    return out;
}
"""

_cpp_src = r"""
#include <torch/extension.h>
torch::Tensor conv3d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                             int64_t stride, int64_t padding, int64_t dilation, int64_t groups);
"""

_ext = load_inline(
    name="custom_conv3d_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["conv3d_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1,
                 padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size, kernel_size)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        # Match nn.Conv3d default initialization
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (in_channels // groups) * kernel_size * kernel_size * kernel_size
            bound = 1.0 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            x = x.to(self.weight.device)
        bias_tensor = self.bias if self.bias is not None else torch.empty(0, device=x.device)
        return _ext.conv3d_forward(
            x, self.weight, bias_tensor,
            self.stride, self.padding, self.dilation, self.groups
        )

